/**
 * n8n Code node - Azure DevOps Service Hook receiver.
 *
 * Configure an ADO Service Hook: Project Settings > Service Hooks > Create subscription
 *   Trigger: "Work item updated"
 *   Filters: Work item type = Bug OR Product Backlog Item (create two subscriptions,
 *            one per type, both pointing at this same webhook)
 *            Optionally filter on "State" = your trigger state (e.g. "Ready for Dev")
 *   Action:  Web Hooks -> URL of this n8n webhook node
 *
 * Normalizes the ADO payload into a BugIntakePayload or PbiIntakePayload and POSTs it
 * to the orchestrator's /runs/start. Does not poll for completion; approvals happen
 * via the dashboard (this same workflow) or chat commands.
 */

const CONFIG = {
  ORCHESTRATOR_URL: 'http://127.0.0.1:4400',
  ORCHESTRATOR_API_KEY: '',
  TRIGGER_STATES: ['ready for dev', 'approved'],
};

const ORCHESTRATOR_URL = ($env.ORCHESTRATOR_URL || CONFIG.ORCHESTRATOR_URL || 'http://127.0.0.1:4400').replace(/\/$/, '');
const API_KEY = $env.ORCHESTRATOR_API_KEY || CONFIG.ORCHESTRATOR_API_KEY;
const ADO_ORG = $env.ADO_ORG || '';

function stripHtml(html) {
  return String(html || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeComponent(areaPath) {
  const v = String(areaPath || '').toLowerCase();
  if (v.includes('frontend') || v.includes('ui') || v.includes('client')) return 'frontend';
  if (v.includes('backend') || v.includes('api') || v.includes('server')) return 'backend';
  return 'unknown';
}

function severityFromAdoSeverity(sev) {
  const v = String(sev || '').toLowerCase();
  if (v.includes('1') || v.includes('critical')) return 'critical';
  if (v.includes('2') || v.includes('high')) return 'high';
  if (v.includes('3') || v.includes('medium')) return 'medium';
  return v.includes('4') || v.includes('low') ? 'low' : 'medium';
}

function reply(json) {
  return [{ json }];
}

const body = $input.first().json ?? {};
const eventType = body.eventType || '';
const resource = body.resource || {};
const fields = resource.revision?.fields || resource.fields || {};

function fieldValue(name) {
  const v = fields[name];
  if (v && typeof v === 'object' && 'newValue' in v) return v.newValue;
  return v;
}

const workItemId = resource.workItemId || resource.id;
const workItemType = String(fieldValue('System.WorkItemType') || '').trim();
const title = String(fieldValue('System.Title') || '').trim();
const state = String(fieldValue('System.State') || '').trim();

if (!workItemId || !workItemType || !title) {
  return reply({ ok: false, message: `Ignored event (eventType=${eventType}): missing workItemId/workItemType/title.` });
}

if (CONFIG.TRIGGER_STATES.length > 0 && !CONFIG.TRIGGER_STATES.includes(state.toLowerCase())) {
  return reply({ ok: true, skipped: true, reason: `State '${state}' not in TRIGGER_STATES`, workItemId });
}

if (!API_KEY) {
  return reply({ ok: false, message: 'Missing ORCHESTRATOR_API_KEY - set automation/n8n-local/.env or CONFIG.ORCHESTRATOR_API_KEY.' });
}

const project = body.resourceContainers?.project?.baseUrl
  ? decodeURIComponent(String(body.resourceContainers.project.baseUrl).split('/').filter(Boolean).pop() || '')
  : (resource.teamProject || '');
const org = ADO_ORG || (body.resourceContainers?.account?.baseUrl
  ? String(body.resourceContainers.account.baseUrl).replace(/https?:\/\//, '').split('.')[0]
  : '');

const workItemUrl = resource._links?.html?.href
  || `https://dev.azure.com/${org}/${encodeURIComponent(project)}/_workitems/edit/${workItemId}`;

const adoRef = {
  workItemId: Number(workItemId),
  workItemType,
  workItemUrl,
  organization: org,
  project,
  areaPath: fieldValue('System.AreaPath'),
  iterationPath: fieldValue('System.IterationPath'),
  tags: String(fieldValue('System.Tags') || '').split(';').map((t) => t.trim()).filter(Boolean),
  state,
};

const assignedToRaw = fieldValue('System.AssignedTo');
const assignedTo = assignedToRaw
  ? {
      email: typeof assignedToRaw === 'object' ? (assignedToRaw.uniqueName || assignedToRaw.email || '') : '',
      name: typeof assignedToRaw === 'object' ? (assignedToRaw.displayName || '') : String(assignedToRaw),
    }
  : undefined;

const reporterEmail = assignedTo?.email || 'ado-webhook@example.com';
const now = new Date().toISOString();
const rev = resource.rev || resource.revision?.rev || 0;
const messageId = `ado-${workItemId}-rev${rev}@${org || 'ado'}`;

const isBug = workItemType.toLowerCase() === 'bug';

const payload = isBug
  ? {
      contractVersion: '1.1.0',
      type: 'bug',
      source: 'ado',
      messageId,
      receivedAt: now,
      reporter: { email: reporterEmail, name: assignedTo?.name },
      bug: {
        title: title.slice(0, 200),
        description: stripHtml(fieldValue('System.Description')).slice(0, 8000) || title,
        severity: severityFromAdoSeverity(fieldValue('Microsoft.VSTS.Common.Severity')),
        component: normalizeComponent(adoRef.areaPath),
        environment: 'ado',
      },
      metadata: { emailSubject: `[ADO Bug #${workItemId}] ${title}`, labels: ['ado', ...adoRef.tags], ado: adoRef },
    }
  : {
      contractVersion: '1.1.0',
      type: 'pbi',
      source: 'ado',
      messageId,
      receivedAt: now,
      reporter: { email: reporterEmail, name: assignedTo?.name },
      ado: adoRef,
      pbi: {
        title: title.slice(0, 200),
        description: stripHtml(fieldValue('System.Description')).slice(0, 20000) || title,
        acceptanceCriteria: stripHtml(fieldValue('Microsoft.VSTS.Common.AcceptanceCriteria')) || undefined,
        storyPoints: fieldValue('Microsoft.VSTS.Scheduling.StoryPoints') ? Number(fieldValue('Microsoft.VSTS.Scheduling.StoryPoints')) : undefined,
        priority: fieldValue('Microsoft.VSTS.Common.Priority') ? Number(fieldValue('Microsoft.VSTS.Common.Priority')) : undefined,
        assignedTo,
      },
      metadata: { adoEventType: eventType, labels: ['ado', ...adoRef.tags] },
    };

try {
  const started = await this.helpers.httpRequest({
    method: 'POST',
    url: `${ORCHESTRATOR_URL}/runs/start`,
    headers: { Authorization: `Bearer ${API_KEY}`, 'Content-Type': 'application/json', Accept: 'application/json' },
    body: payload,
    json: true,
    timeout: 30000,
  });

  return reply({
    ok: true,
    runId: started.runId,
    status: started.status,
    type: started.type,
    branchName: started.branchName,
    workItemId,
    message: `Started ${isBug ? 'bug-fix' : 'PBI'} run ${started.runId} for ADO work item #${workItemId}.`,
  });
} catch (err) {
  const status = err.statusCode ?? err.response?.statusCode ?? 'unknown';
  const errBody = err.response?.body ?? err.response?.data ?? err.message;
  if (status === 409) {
    return reply({ ok: true, skipped: true, reason: 'Run already exists for this work item revision', workItemId });
  }
  return reply({ ok: false, message: `Orchestrator error (HTTP ${status}): ${JSON.stringify(errBody)}`, workItemId });
}

/**
 * n8n Code node - staging deploy trigger + poll, driven by the orchestrator's
 * outbound webhook events (N8N_EVENT_WEBHOOK_URL in automation/orchestrator/.env or .env.pci).
 * Only acts on event === "pr.created". Dispatches a GitHub Actions workflow, polls until
 * it finishes, then reports the result back via POST /runs/:id/deploy-status.
 *
 * Adapting to Azure Pipelines: replace the two githubRequest calls with the Azure Pipelines
 * REST API (POST .../_apis/pipelines/{pipelineId}/runs to start, GET .../runs/{runId} to poll).
 */

const CONFIG = {
  ORCHESTRATOR_URL: 'http://127.0.0.1:4400',
  ORCHESTRATOR_API_KEY: '',
  GITHUB_TOKEN: '',
  GITHUB_OWNER: 'Hishitha-GJ',
  GITHUB_REPO: 'react_project_Health_Insurance_Claim_Management',
  GITHUB_DEPLOY_WORKFLOW_FILE: 'deploy-staging.yml',
  STAGING_ENVIRONMENT: 'staging',
  STAGING_URL_TEMPLATE: '',
  MAX_POLL_ATTEMPTS: 180,
  POLL_INTERVAL_MS: 10000,
};

const ORCHESTRATOR_URL = ($env.ORCHESTRATOR_URL || CONFIG.ORCHESTRATOR_URL).replace(/\/$/, '');
const API_KEY = $env.ORCHESTRATOR_API_KEY || CONFIG.ORCHESTRATOR_API_KEY;
const GITHUB_TOKEN = $env.GITHUB_TOKEN || CONFIG.GITHUB_TOKEN;
const GITHUB_OWNER = $env.GITHUB_OWNER || CONFIG.GITHUB_OWNER;
const GITHUB_REPO = $env.GITHUB_REPO || CONFIG.GITHUB_REPO;

function reply(json) { return [{ json }]; }

async function orchestratorRequest(method, path, body) {
  return this.helpers.httpRequest({
    method, url: `${ORCHESTRATOR_URL}${path}`,
    headers: { Authorization: `Bearer ${API_KEY}`, 'Content-Type': 'application/json', Accept: 'application/json' },
    body, json: true, timeout: 30000,
  });
}

async function githubRequest(method, path, body) {
  return this.helpers.httpRequest({
    method, url: `https://api.github.com${path}`,
    headers: { Authorization: `Bearer ${GITHUB_TOKEN}`, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json', 'User-Agent': 'sdlc-orchestrator-n8n', 'X-GitHub-Api-Version': '2022-11-28' },
    body, json: true, timeout: 30000, returnFullResponse: true,
  });
}

const event = $input.first().json ?? {};

if (event.event !== 'pr.created') {
  return reply({ ok: true, skipped: true, reason: `Ignoring event '${event.event}'` });
}
if (!API_KEY || !GITHUB_TOKEN) {
  return reply({ ok: false, message: 'Missing ORCHESTRATOR_API_KEY or GITHUB_TOKEN in node config / n8n env. (For Azure Repos targets, adapt this node to Azure Pipelines instead.)' });
}

const { runId, branchName } = event;
if (!runId || !branchName) {
  return reply({ ok: false, message: 'Event payload missing runId/branchName.' });
}

try {
  await orchestratorRequest.call(this, 'POST', `/runs/${runId}/deploy-status`, {
    status: 'in_progress', environment: CONFIG.STAGING_ENVIRONMENT, note: `Dispatching ${CONFIG.GITHUB_DEPLOY_WORKFLOW_FILE} on ${branchName}`,
  });

  await githubRequest.call(this, 'POST', `/repos/${GITHUB_OWNER}/${GITHUB_REPO}/actions/workflows/${CONFIG.GITHUB_DEPLOY_WORKFLOW_FILE}/dispatches`, { ref: branchName });

  let runsList;
  for (let findAttempt = 0; findAttempt < 6; findAttempt++) {
    await new Promise((r) => setTimeout(r, 3000));
    runsList = await githubRequest.call(this, 'GET', `/repos/${GITHUB_OWNER}/${GITHUB_REPO}/actions/workflows/${CONFIG.GITHUB_DEPLOY_WORKFLOW_FILE}/runs?branch=${encodeURIComponent(branchName)}&per_page=1`);
    if (runsList.body?.workflow_runs?.length > 0) break;
  }

  const run = runsList?.body?.workflow_runs?.[0];
  if (!run) {
    await orchestratorRequest.call(this, 'POST', `/runs/${runId}/deploy-status`, { status: 'failed', note: 'Dispatched workflow but could not find the resulting run.' });
    return reply({ ok: false, runId, message: 'Workflow dispatched but run not found after 18s.' });
  }

  const pipelineRunUrl = run.html_url;
  let conclusion = run.conclusion;
  let currentRunId = run.id;

  for (let attempt = 0; attempt < CONFIG.MAX_POLL_ATTEMPTS && !conclusion; attempt++) {
    await new Promise((r) => setTimeout(r, CONFIG.POLL_INTERVAL_MS));
    const check = await githubRequest.call(this, 'GET', `/repos/${GITHUB_OWNER}/${GITHUB_REPO}/actions/runs/${currentRunId}`);
    conclusion = check.body?.conclusion;
  }

  const succeeded = conclusion === 'success';
  await orchestratorRequest.call(this, 'POST', `/runs/${runId}/deploy-status`, {
    status: succeeded ? 'succeeded' : 'failed', environment: CONFIG.STAGING_ENVIRONMENT, url: CONFIG.STAGING_URL_TEMPLATE || undefined, pipelineRunUrl, note: conclusion ? `Workflow conclusion: ${conclusion}` : 'Timed out waiting for workflow to finish.',
  });

  return reply({ ok: true, runId, deployStatus: succeeded ? 'succeeded' : 'failed', pipelineRunUrl, message: `Deploy ${succeeded ? 'succeeded' : 'failed'} for run ${runId} (${branchName}).` });
} catch (err) {
  const status = err.statusCode ?? err.response?.statusCode ?? 'unknown';
  const message = `Deploy trigger/poll error (HTTP ${status}): ${err.message}`;
  try {
    await orchestratorRequest.call(this, 'POST', `/runs/${runId}/deploy-status`, { status: 'failed', note: message });
  } catch { /* best-effort */ }
  return reply({ ok: false, runId, message });
}

function unwrap(raw){if(!raw||typeof raw!=='object')return{message:String(raw==null?'':raw)};if(raw.body!=null){if(typeof raw.body==='string'){try{return JSON.parse(raw.body);}catch(e){return{message:raw.body};}}if(typeof raw.body==='object'&&!Array.isArray(raw.body))return raw.body;}return raw;}
const ALLOWED=['start','status','view-plan','approve-plan','reject-plan','approve','reject','create-pr','uat-approve','uat-reject','cancel','health'];
const raw=$input.first().json||{};
const p=unwrap(raw);
const action=String(p.action||'start').toLowerCase().trim();
const runId=String(p.runId||'').trim();
const workItemType=String(p.workItemType||'bug').toLowerCase()==='pbi'?'pbi':'bug';
const message=String(p.message||'').trim();
const title=String(p.title||'').trim();
const description=String(p.description||'').trim();
const acceptanceCriteria=String(p.acceptanceCriteria||'').trim();
const storyPoints=p.storyPoints?Number(p.storyPoints):undefined;
const adoWorkItemId=p.adoWorkItemId?Number(p.adoWorkItemId):undefined;
const reporterEmail=String(p.reporterEmail||'dashboard@example.com').trim();
const comment=String(p.comment||'').trim();
const createPr=Boolean(p.createPr);
const draft=Boolean(p.draft);
if(ALLOWED.indexOf(action)===-1){return[{json:{action:'error',error:'Unknown action: '+action}}];}
const needsRunId=['status','view-plan','approve-plan','reject-plan','approve','reject','create-pr','uat-approve','uat-reject','cancel'].indexOf(action)!==-1;
if(needsRunId&&!runId){return[{json:{action:'error',error:'Run ID is required for action: '+action}}];}
if(action==='start'&&workItemType==='bug'&&!message){return[{json:{action:'error',error:'Bug report text is required.'}}];}
if(action==='start'&&workItemType==='pbi'&&(!title||!description)){return[{json:{action:'error',error:'Title and description are required for a PBI.'}}];}
return[{json:{action,runId,workItemType,message,title,description,acceptanceCriteria,storyPoints,adoWorkItemId,reporterEmail,comment,createPr,draft}}];

const e=$input.first().json||{};
const lines=['Invalid request: '+(e.error||'unknown error'),'','Available actions:','  start          - report a new bug or PBI','  status         - check run status (runId)','  view-plan      - view PBI plan, Gate 1 (runId)','  approve-plan   - approve PBI plan (runId)','  reject-plan    - reject PBI plan (runId, comment)','  approve        - approve patch, Gate 2 (runId)','  reject         - reject patch (runId, comment)','  create-pr      - create pull request (runId)','  uat-approve    - approve UAT and release (runId)','  uat-reject     - reject UAT (runId, comment)','  cancel         - cancel in-flight run (runId)','  health         - orchestrator health check'].join('\n');
return[{json:{response:lines}}];

const ORCH=($env.ORCHESTRATOR_URL||'http://127.0.0.1:4400');const BASE=ORCH.endsWith('/')?ORCH.slice(0,-1):ORCH;const KEY=$env.ORCHESTRATOR_API_KEY||'';
async function req(m,p,b){return await this.helpers.httpRequest({method:m,url:BASE+p,headers:{Authorization:'Bearer '+KEY,'Content-Type':'application/json',Accept:'application/json'},body:b,json:true,timeout:120000});}
const ALLOWED_COMPONENTS=['frontend','backend','fullstack','unknown'];
const ALLOWED_SEVERITIES=['low','medium','high','critical'];
function normComponent(v){var s=String(v||'unknown').toLowerCase().trim();if(ALLOWED_COMPONENTS.indexOf(s)!==-1)return s;if(s.indexOf('front')!==-1)return 'frontend';if(s.indexOf('back')!==-1||s.indexOf('api')!==-1||s.indexOf('dotnet')!==-1)return 'backend';if(s.indexOf('full')!==-1)return 'fullstack';return 'unknown';}
function normSeverity(v){var s=String(v||'medium').toLowerCase().trim();return ALLOWED_SEVERITIES.indexOf(s)!==-1?s:'medium';}
function parseBugText(text){var body=text;var title='Bug report from dashboard';var component='unknown';var affectedArea;var severity='medium';var bugIdx=text.toLowerCase().indexOf('[bug]');if(bugIdx===0){var nl=text.indexOf('\n');var firstLine=nl===-1?text:text.slice(0,nl);title=firstLine.replace(/\[bug\]/i,'').trim().slice(0,200);body=nl===-1?'':text.slice(nl+1).trim();}else{var lines=text.split('\n').map(function(l){return l.trim();}).filter(Boolean);if(lines.length>0){title=lines[0].slice(0,200);body=lines.slice(1).join('\n')||title;}}
var bodyLines=body.split('\n');bodyLines.forEach(function(l){var lower=l.toLowerCase();if(lower.indexOf('component:')===0)component=normComponent(l.slice(10));if(lower.indexOf('area:')===0)affectedArea=l.slice(5).trim();if(lower.indexOf('severity:')===0)severity=normSeverity(l.slice(9));});
var bug={title:title,description:(body.trim()||title).slice(0,8000),severity:severity,component:component,environment:'local-dev'};if(affectedArea)bug.affectedArea=affectedArea;return bug;}
const d=$input.first().json;
const now=new Date().toISOString();
const msgId='dash-'+Date.now()+'-'+Math.random().toString(36).slice(2,8)+'@local';
let payload;
let pbiAdoNote='';
if(d.workItemType==='pbi'){
  var org=String($env.ADO_ORG||'local-test').trim();
  var project=String($env.ADO_PROJECT||'Dashboard Manual Testing').trim();
  var isRealAdo=Boolean(d.adoWorkItemId);
  var workItemId=isRealAdo?Number(d.adoWorkItemId):(900000000+(Date.now()%100000));
  var workItemUrl=isRealAdo
    ? 'https://dev.azure.com/'+encodeURIComponent(org)+'/'+encodeURIComponent(project)+'/_workitems/edit/'+workItemId
    : 'local-dashboard://manual-pbi/'+workItemId;
  var adoRef={workItemId:workItemId,workItemType:'Product Backlog Item',workItemUrl:workItemUrl,organization:org,project:project,state:isRealAdo?'Active':'Manual Test',tags:isRealAdo?['dashboard']:['dashboard','dummy-ado-id']};
  pbiAdoNote=isRealAdo?('Linked to ADO work item #'+workItemId+'.'):('No ADO work item supplied - using local test ID #'+workItemId+' (not written back to ADO).');
  payload={contractVersion:'1.1.0',type:'pbi',source:'ado',messageId:msgId,receivedAt:now,reporter:{email:d.reporterEmail,name:'Dashboard User'},ado:adoRef,pbi:{title:d.title.slice(0,200),description:d.description.slice(0,20000),acceptanceCriteria:d.acceptanceCriteria||undefined,storyPoints:d.storyPoints},metadata:{adoEventType:'dashboard.manual.start',labels:['dashboard','demo']}};
}else{
  var bug=parseBugText(d.message);
  payload={contractVersion:'1.1.0',type:'bug',source:'chat',messageId:msgId,receivedAt:now,reporter:{email:d.reporterEmail,name:'Dashboard User'},bug:bug,metadata:{emailSubject:'[BUG] '+bug.title,labels:['dashboard','demo']}};
}
try{
  const started=await req.call(this,'POST','/runs/start',payload);
  const lines=['Started '+(d.workItemType==='pbi'?'PBI':'bug-fix')+' run: '+started.runId,'Branch: '+(started.branchName||'pending'),'Status: '+started.status,pbiAdoNote,'','Switch to the Track tab to monitor progress.'].filter(Boolean).join('\n');
  return[{json:{response:lines,runId:started.runId,status:started.status}}];
}catch(err){
  const body=err.response&&(err.response.body||err.response.data);
  const detail=(body&&body.error&&body.error.message)||err.message||'Failed to start run';
  const hint=String(detail).indexOf('REPO_LOCK_HELD')!==-1?'\n\nAnother run is active. Check its status and approve/reject/cancel it first.':'';
  return[{json:{response:'Error starting run: '+detail+hint}}];
}

const ORCH=($env.ORCHESTRATOR_URL||'http://127.0.0.1:4400');const BASE=ORCH.endsWith('/')?ORCH.slice(0,-1):ORCH;const KEY=$env.ORCHESTRATOR_API_KEY||'';
async function req(m,p,b){return await this.helpers.httpRequest({method:m,url:BASE+p,headers:{Authorization:'Bearer '+KEY,'Content-Type':'application/json',Accept:'application/json'},body:b,json:true,timeout:30000});}
try{
  const d=$input.first().json;
  const run=await req.call(this,'GET','/runs/'+d.runId);
  return[{json:{response:'Loaded status for '+run.runId,runId:run.runId,status:run.status,run:run}}];
}catch(err){
  const body=err.response&&(err.response.body||err.response.data);
  const isTimeout=/timeout/i.test(err.message||'');
  if(isTimeout&&!body){
    return[{json:{response:'Orchestrator did not respond in time - it may be busy running a live agent turn (planning/coding can take several minutes for real PBIs). This will keep auto-refreshing; no action needed.'}}];
  }
  const detail=(body&&body.error&&body.error.message)||err.message||'Could not fetch status';
  return[{json:{response:'Error: '+detail}}];
}

const ORCH=($env.ORCHESTRATOR_URL||'http://127.0.0.1:4400');const BASE=ORCH.endsWith('/')?ORCH.slice(0,-1):ORCH;const KEY=$env.ORCHESTRATOR_API_KEY||'';
async function req(m,p,b){return await this.helpers.httpRequest({method:m,url:BASE+p,headers:{Authorization:'Bearer '+KEY,'Content-Type':'application/json',Accept:'application/json'},body:b,json:true,timeout:30000});}
try{
  const d=$input.first().json;
  const info=await req.call(this,'GET','/runs/'+d.runId+'/plan');
  const lines=['Plan for '+d.runId+' (status: '+info.status+')','',info.planMarkdown||'(no plan text)'].join('\n');
  return[{json:{response:lines,runId:d.runId,status:info.status}}];
}catch(err){
  const body=err.response&&(err.response.body||err.response.data);
  const detail=(body&&body.error&&body.error.message)||err.message||'Could not fetch plan';
  return[{json:{response:'Error: '+detail}}];
}

const ORCH=($env.ORCHESTRATOR_URL||'http://127.0.0.1:4400');const BASE=ORCH.endsWith('/')?ORCH.slice(0,-1):ORCH;const KEY=$env.ORCHESTRATOR_API_KEY||'';
async function req(m,p,b){return await this.helpers.httpRequest({method:m,url:BASE+p,headers:{Authorization:'Bearer '+KEY,'Content-Type':'application/json',Accept:'application/json'},body:b,json:true,timeout:60000});}
try{
  const d=$input.first().json;
  const r=await req.call(this,'POST','/runs/'+d.runId+'/approve-plan',{approvedBy:d.reporterEmail||'dashboard@example.com',comment:d.comment||'Approved via dashboard'});
  const lines=['Plan approved for '+d.runId,'Status: '+r.status,'','Coding will start automatically.'].join('\n');
  return[{json:{response:lines,runId:d.runId,status:r.status}}];
}catch(err){
  const body=err.response&&(err.response.body||err.response.data);
  const detail=(body&&body.error&&body.error.message)||err.message||'Could not approve plan';
  return[{json:{response:'Error: '+detail}}];
}

const ORCH=($env.ORCHESTRATOR_URL||'http://127.0.0.1:4400');const BASE=ORCH.endsWith('/')?ORCH.slice(0,-1):ORCH;const KEY=$env.ORCHESTRATOR_API_KEY||'';
async function req(m,p,b){return await this.helpers.httpRequest({method:m,url:BASE+p,headers:{Authorization:'Bearer '+KEY,'Content-Type':'application/json',Accept:'application/json'},body:b,json:true,timeout:30000});}
try{
  const d=$input.first().json;
  const r=await req.call(this,'POST','/runs/'+d.runId+'/reject-plan',{rejectedBy:d.reporterEmail||'dashboard@example.com',reason:d.comment||'Rejected via dashboard'});
